// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// VendorListVendors The tenant's vendor / processor registry (VEN-01)
	// (GET /admin/v1/vendors)
	VendorListVendors(ctx context.Context, request VendorListVendorsRequestObject) (VendorListVendorsResponseObject, error)
	// VendorCreateVendor Register a vendor/processor against an existing external party (ORG-06) — always starts prospect (ST-06)
	// (POST /admin/v1/vendors)
	VendorCreateVendor(ctx context.Context, request VendorCreateVendorRequestObject) (VendorCreateVendorResponseObject, error)
	// VendorGetVendor One vendor's full profile — the acceptance criterion's single page (VEN-01)
	// (GET /admin/v1/vendors/{id})
	VendorGetVendor(ctx context.Context, request VendorGetVendorRequestObject) (VendorGetVendorResponseObject, error)
	// VendorUpdateVendor Change a vendor's profile — never its status/tier (ST-06's own transitions, owned by sibling features)
	// (PATCH /admin/v1/vendors/{id})
	VendorUpdateVendor(ctx context.Context, request VendorUpdateVendorRequestObject) (VendorUpdateVendorResponseObject, error)
	// VendorListAssessments A vendor's own assessment cycles, newest first (VEN-07)
	// (GET /admin/v1/vendors/{id}/assessments)
	VendorListAssessments(ctx context.Context, request VendorListAssessmentsRequestObject) (VendorListAssessmentsResponseObject, error)
	// VendorRecordAssessment Answer one of VEN-04's published vendor templates once: the score and the resulting risk level on this tenant's own matrix (VEN-07)
	// (POST /admin/v1/vendors/{id}/assessments)
	VendorRecordAssessment(ctx context.Context, request VendorRecordAssessmentRequestObject) (VendorRecordAssessmentResponseObject, error)
	// VendorDecideAssessment Approve / reject / conditionally approve an answered assessment cycle (VEN-08)
	// (POST /admin/v1/vendors/{id}/assessments/{assessmentId}/decision)
	VendorDecideAssessment(ctx context.Context, request VendorDecideAssessmentRequestObject) (VendorDecideAssessmentResponseObject, error)
	// VendorListCertificates A vendor's evidence & compliance certificates (VEN-06, ISO 27001, SOC 2, …)
	// (GET /admin/v1/vendors/{id}/certificates)
	VendorListCertificates(ctx context.Context, request VendorListCertificatesRequestObject) (VendorListCertificatesResponseObject, error)
	// VendorAddCertificate Record a certificate — its evidence file schedules this feature's own expiry reminder once valid_to is set
	// (POST /admin/v1/vendors/{id}/certificates)
	VendorAddCertificate(ctx context.Context, request VendorAddCertificateRequestObject) (VendorAddCertificateResponseObject, error)
	// VendorDeleteCertificate Remove a certificate record (not its evidence file)
	// (DELETE /admin/v1/vendors/{id}/certificates/{certificateId})
	VendorDeleteCertificate(ctx context.Context, request VendorDeleteCertificateRequestObject) (VendorDeleteCertificateResponseObject, error)
	// VendorListIntakes A vendor's tiering rounds, newest first (VEN-02)
	// (GET /admin/v1/vendors/{id}/intakes)
	VendorListIntakes(ctx context.Context, request VendorListIntakesRequestObject) (VendorListIntakesResponseObject, error)
	// VendorRecordIntake Answer the intake questionnaire once — the system computes the tier and the assessment templates it now requires (VEN-02)
	// (POST /admin/v1/vendors/{id}/intakes)
	VendorRecordIntake(ctx context.Context, request VendorRecordIntakeRequestObject) (VendorRecordIntakeResponseObject, error)
	// VendorGetOffboarding The vendor's current offboarding record, if one is in progress or finished (VEN-14)
	// (GET /admin/v1/vendors/{id}/offboarding)
	VendorGetOffboarding(ctx context.Context, request VendorGetOffboardingRequestObject) (VendorGetOffboardingResponseObject, error)
	// VendorUpdateOffboarding Record data-return progress — status, destruction certificate, access revocation (If-Match)
	// (PUT /admin/v1/vendors/{id}/offboarding)
	VendorUpdateOffboarding(ctx context.Context, request VendorUpdateOffboardingRequestObject) (VendorUpdateOffboardingResponseObject, error)
	// VendorListRemediationItems A vendor's remediation plan — items opened by conditional approvals (VEN-08)
	// (GET /admin/v1/vendors/{id}/remediation-items)
	VendorListRemediationItems(ctx context.Context, request VendorListRemediationItemsRequestObject) (VendorListRemediationItemsResponseObject, error)
	// VendorTransitionVendor Move the vendor along ST-06 — start offboarding, or terminate once data return and access revocation are complete (If-Match; VEN-14 is the terminated edge's own acceptance criterion)
	// (POST /admin/v1/vendors/{id}/transitions)
	VendorTransitionVendor(ctx context.Context, request VendorTransitionVendorRequestObject) (VendorTransitionVendorResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

